import React from 'react';

const TaskCard = ({ task, onUpdate, onDelete, onEdit }) => {
  const { _id, title, description, priority, status, dueDate } = task;

  const isCompleted = status === 'Completed';

  // Format date
  const formatDate = (dateStr) => {
    if (!dateStr) return 'No due date';
    const date = new Date(dateStr);
    return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  };

  // Determine priority color
  const getPriorityColor = (p) => {
    switch (p) {
      case 'High': return 'danger';
      case 'Medium': return 'warning';
      case 'Low': return 'info';
      default: return 'secondary';
    }
  };

  const handleToggleStatus = () => {
    const newStatus = isCompleted ? 'Pending' : 'Completed';
    onUpdate(_id, { status: newStatus });
  };

  return (
    <div className={`task-card ${isCompleted ? 'task-completed' : ''}`}>
      <div className="task-card-inner">
        {/* Checkbox / Status Toggle */}
        <div className="task-status-toggle" onClick={handleToggleStatus} role="button" aria-label="Toggle task status">
          <div className={`custom-checkbox ${isCompleted ? 'checked' : ''}`}>
            {isCompleted && <i className="bi bi-check"></i>}
          </div>
        </div>

        {/* Task Details */}
        <div className="task-content">
          <div className="d-flex justify-content-between align-items-start mb-1">
            <h5 className="task-title m-0">{title}</h5>
            <div className="task-actions">
              <button className="btn-action btn-edit" onClick={() => onEdit(task)} title="Edit Task">
                <i className="bi bi-pencil-square"></i>
              </button>
              <button className="btn-action btn-delete" onClick={() => onDelete(_id)} title="Delete Task">
                <i className="bi bi-trash"></i>
              </button>
            </div>
          </div>

          {description && <p className="task-description">{description}</p>}

          <div className="task-meta mt-3">
            <span className={`badge bg-${getPriorityColor(priority)} bg-opacity-10 text-${getPriorityColor(priority)} border border-${getPriorityColor(priority)} rounded-pill px-3 py-1 fw-medium`}>
              {priority} Priority
            </span>
            <span className="task-date text-muted ms-3">
              <i className="bi bi-calendar-event me-1"></i>
              {formatDate(dueDate)}
            </span>
            <span className={`badge ${isCompleted ? 'bg-success' : 'bg-secondary'} ms-auto rounded-pill`}>
               {status}
            </span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TaskCard;
